package com.barrowssarcophagusmemory;

enum BarrowsBrother
{
    DHAROK("Dharok", 20720, 36, 52, 52, 31),
    AHRIM("Ahrim", 20770, 36, 37, 45, 28),
    VERAC("Verac", 20772, 55, 42, 39, 36),
    TORAG("Torag", 20721, 49, 20, 36, 17),
    KARIL("Karil", 20771, 29, 20, 46, 15),
    GUTHAN("Guthan", 20722, 17, 40, 54, 20);

    private final String displayName;
    private final int sarcophagusObjectId;
    private final int cryptRegionX;
    private final int cryptRegionY;
    private final int surfaceRegionX;
    private final int surfaceRegionY;

    BarrowsBrother(
        String displayName,
        int sarcophagusObjectId,
        int cryptRegionX,
        int cryptRegionY,
        int surfaceRegionX,
        int surfaceRegionY)
    {
        this.displayName = displayName;
        this.sarcophagusObjectId = sarcophagusObjectId;
        this.cryptRegionX = cryptRegionX;
        this.cryptRegionY = cryptRegionY;
        this.surfaceRegionX = surfaceRegionX;
        this.surfaceRegionY = surfaceRegionY;
    }

    String getDisplayName()
    {
        return displayName;
    }

    int getSarcophagusObjectId()
    {
        return sarcophagusObjectId;
    }

    int getCryptRegionX()
    {
        return cryptRegionX;
    }

    int getCryptRegionY()
    {
        return cryptRegionY;
    }

    int getSurfaceRegionX()
    {
        return surfaceRegionX;
    }

    int getSurfaceRegionY()
    {
        return surfaceRegionY;
    }

    boolean matchesNpcName(String npcName)
    {
        return npcName != null
            && (npcName.equals(displayName) || npcName.startsWith(displayName + " "));
    }

    static BarrowsBrother fromSarcophagusObjectId(int objectId)
    {
        for (BarrowsBrother brother : values())
        {
            if (brother.sarcophagusObjectId == objectId)
            {
                return brother;
            }
        }

        return null;
    }
}

package com.barrowssarcophagusmemory;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BarrowsSarcophagusMemoryConfig.GROUP)
public interface BarrowsSarcophagusMemoryConfig extends Config
{
    String GROUP = "barrows-sarcophagus-memory";

    @ConfigSection(
        name = "Brother tiles",
        description = "Fixed labels for the six Barrows brothers.",
        position = 0
    )
    String BROTHER_TILES_SECTION = "brotherTiles";

    @ConfigSection(
        name = "Tunnel memory",
        description = "The remembered sarcophagus that leads to the tunnels.",
        position = 1
    )
    String TUNNEL_MEMORY_SECTION = "tunnelMemory";

    @ConfigItem(
        keyName = "showCryptBrotherTiles",
        name = "Show crypt brother tiles",
        description = "Display the six labelled sarcophagus tiles inside the crypt.",
        section = BROTHER_TILES_SECTION,
        position = 0
    )
    default boolean showCryptBrotherTiles()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showSurfaceBrotherTiles",
        name = "Show surface brother tiles",
        description = "Display the six labelled mound tiles above the crypts.",
        section = BROTHER_TILES_SECTION,
        position = 1
    )
    default boolean showSurfaceBrotherTiles()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        keyName = "brotherTileColor",
        name = "Brother tile color",
        description = "Color used for brother tiles and labels when they are not the tunnel.",
        section = BROTHER_TILES_SECTION,
        position = 2
    )
    default Color brotherTileColor()
    {
        // #FFFF8D8D in AARRGGBB notation.
        return new Color(0xFF, 0x8D, 0x8D, 0xFF);
    }

    @ConfigItem(
        keyName = "showTunnelSarcophagus",
        name = "Show tunnel markers",
        description = "Highlight the tunnel sarcophagus and its matching labelled tiles.",
        section = TUNNEL_MEMORY_SECTION,
        position = 0
    )
    default boolean showTunnelSarcophagus()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        keyName = "tunnelSarcophagusColor",
        name = "Tunnel highlight color",
        description = "Color used for the tunnel sarcophagus, tile, and labels.",
        section = TUNNEL_MEMORY_SECTION,
        position = 1
    )
    default Color tunnelSarcophagusColor()
    {
        // #FF26FF00 in AARRGGBB notation.
        return new Color(0x26, 0xFF, 0x00, 0xFF);
    }

    @ConfigItem(
        keyName = "showTunnelInfoBox",
        name = "Show tunnel infobox",
        description = "Show a tunnel reminder above ground or inside the crypt, including a question-mark icon while unknown.",
        section = TUNNEL_MEMORY_SECTION,
        position = 2
    )
    default boolean showTunnelInfoBox()
    {
        return true;
    }
}

package com.barrowssarcophagusmemory;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

final class BarrowsSarcophagusMemoryOverlay extends Overlay
{
    private static final int ABOVE_GROUND_REGION_ID = 14131;
    private static final int CRYPT_REGION_ID = 14231;
    private static final int CRYPT_PLANE = 3;
    private static final Stroke TILE_STROKE = new BasicStroke(2.0f);
    private static final Stroke OBJECT_STROKE = new BasicStroke(3.0f);

    private final Client client;
    private final BarrowsSarcophagusMemoryPlugin plugin;
    private final BarrowsSarcophagusMemoryConfig config;

    @Inject
    BarrowsSarcophagusMemoryOverlay(
        Client client,
        BarrowsSarcophagusMemoryPlugin plugin,
        BarrowsSarcophagusMemoryConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null)
        {
            return null;
        }

        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        BarrowsBrother tunnelBrother = plugin.getTunnelBrother();

        if (regionId == ABOVE_GROUND_REGION_ID)
        {
            if (config.showSurfaceBrotherTiles())
            {
                renderBrotherTiles(graphics, regionId, tunnelBrother, true);
            }
            return null;
        }

        if (regionId != CRYPT_REGION_ID
            || client.getLocalPlayer().getWorldLocation().getPlane() != CRYPT_PLANE)
        {
            return null;
        }

        if (config.showCryptBrotherTiles())
        {
            renderBrotherTiles(graphics, regionId, tunnelBrother, false);
        }
        else if (config.showTunnelSarcophagus() && tunnelBrother != null)
        {
            renderSingleTile(graphics, regionId, tunnelBrother, false, true, false);
        }

        if (config.showTunnelSarcophagus() && tunnelBrother != null)
        {
            renderTunnelSarcophagus(graphics, tunnelBrother);
        }

        return null;
    }

    private void renderBrotherTiles(
        Graphics2D graphics,
        int regionId,
        BarrowsBrother tunnelBrother,
        boolean surface)
    {
        for (BarrowsBrother brother : BarrowsBrother.values())
        {
            boolean showTunnelState = config.showTunnelSarcophagus();
            boolean isTunnel = showTunnelState && brother == tunnelBrother;
            boolean isNoTunnel = showTunnelState
                && (tunnelBrother != null
                    ? brother != tunnelBrother
                    : plugin.isBrotherEmpty(brother));
            renderSingleTile(graphics, regionId, brother, surface, isTunnel, isNoTunnel);
        }
    }

    private void renderSingleTile(
        Graphics2D graphics,
        int regionId,
        BarrowsBrother brother,
        boolean surface,
        boolean isTunnel,
        boolean isNoTunnel)
    {
        WorldView worldView = client.getLocalPlayer().getWorldView();
        int plane = worldView.getPlane();
        int regionX = surface ? brother.getSurfaceRegionX() : brother.getCryptRegionX();
        int regionY = surface ? brother.getSurfaceRegionY() : brother.getCryptRegionY();

        WorldPoint worldPoint = WorldPoint.fromRegion(regionId, regionX, regionY, plane);
        LocalPoint localPoint = LocalPoint.fromWorld(worldView, worldPoint);
        if (localPoint == null)
        {
            return;
        }

        Polygon polygon = Perspective.getCanvasTilePoly(client, localPoint);
        if (polygon == null)
        {
            return;
        }

        Color markerColor = isTunnel
            ? config.tunnelSarcophagusColor()
            : config.brotherTileColor();
        Color fillColor = new Color(
            markerColor.getRed(),
            markerColor.getGreen(),
            markerColor.getBlue(),
            Math.min(markerColor.getAlpha(), 50));
        String label = brother.getDisplayName()
            + (isTunnel ? " [Tunnel]" : (isNoTunnel ? " [No Tunnel]" : ""));

        Font previousFont = graphics.getFont();
        Stroke previousStroke = graphics.getStroke();
        Color previousColor = graphics.getColor();

        graphics.setFont(FontManager.getRunescapeBoldFont());
        graphics.setStroke(TILE_STROKE);
        graphics.setColor(fillColor);
        graphics.fill(polygon);
        graphics.setColor(markerColor);
        graphics.draw(polygon);

        Point textLocation = Perspective.getCanvasTextLocation(
            client,
            graphics,
            localPoint,
            label,
            0);

        if (textLocation != null)
        {
            OverlayUtil.renderTextLocation(graphics, textLocation, label, markerColor);
        }

        graphics.setFont(previousFont);
        graphics.setStroke(previousStroke);
        graphics.setColor(previousColor);
    }

    private void renderTunnelSarcophagus(Graphics2D graphics, BarrowsBrother tunnelBrother)
    {
        WorldView worldView = client.getLocalPlayer().getWorldView();
        int plane = worldView.getPlane();
        WorldPoint markerPoint = WorldPoint.fromRegion(
            CRYPT_REGION_ID,
            tunnelBrother.getCryptRegionX(),
            tunnelBrother.getCryptRegionY(),
            plane);
        LocalPoint markerLocalPoint = LocalPoint.fromWorld(worldView, markerPoint);
        if (markerLocalPoint == null)
        {
            return;
        }

        Scene scene = worldView.getScene();
        Tile[][][] tiles = scene.getTiles();
        if (plane < 0 || plane >= tiles.length)
        {
            return;
        }

        int minSceneX = Math.max(0, markerLocalPoint.getSceneX() - 4);
        int maxSceneX = Math.min(tiles[plane].length - 1, markerLocalPoint.getSceneX() + 4);
        int minSceneY = Math.max(0, markerLocalPoint.getSceneY() - 4);
        int maxSceneY = Math.min(tiles[plane][0].length - 1, markerLocalPoint.getSceneY() + 4);

        Stroke previousStroke = graphics.getStroke();
        Color previousColor = graphics.getColor();
        graphics.setStroke(OBJECT_STROKE);
        graphics.setColor(config.tunnelSarcophagusColor());

        for (int sceneX = minSceneX; sceneX <= maxSceneX; sceneX++)
        {
            for (int sceneY = minSceneY; sceneY <= maxSceneY; sceneY++)
            {
                Tile tile = tiles[plane][sceneX][sceneY];
                if (tile == null)
                {
                    continue;
                }

                GameObject[] gameObjects = tile.getGameObjects();
                if (gameObjects == null)
                {
                    continue;
                }

                for (GameObject gameObject : gameObjects)
                {
                    if (gameObject == null
                        || gameObject.getId() != tunnelBrother.getSarcophagusObjectId()
                        || !gameObject.getSceneMinLocation().equals(tile.getSceneLocation()))
                    {
                        continue;
                    }

                    Shape hull = gameObject.getConvexHull();
                    if (hull != null)
                    {
                        graphics.draw(hull);
                    }
                }
            }
        }

        graphics.setStroke(previousStroke);
        graphics.setColor(previousColor);
    }
}

package com.barrowssarcophagusmemory;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Barrows Sarcophagus Memory",
    description = "Labels Barrows sarcophagi and remembers which one leads to the tunnels if you leave pre-maturely.",
    tags = {"barrows", "sarcophagus", "sarcophagi", "tunnel", "memory", "brothers"}
)
public class BarrowsSarcophagusMemoryPlugin extends Plugin
{
    private static final int ABOVE_GROUND_REGION_ID = 14131;
    private static final int CRYPT_REGION_ID = 14231;


    private static final int PENDING_SARCOPHAGUS_TICKS = 50;
    private static final String TUNNEL_BROTHER_CONFIG_KEY = "rememberedTunnelBrother";
    private static final String EMPTY_BROTHERS_CONFIG_KEY = "emptySarcophagi";

    private static final String HIDDEN_TUNNEL_PROMPT =
        "You've found a hidden tunnel, do you want to enter?";
    private static final String HIDDEN_TUNNEL_YES = "Yeah I'm fearless!";
    private static final String HIDDEN_TUNNEL_NO = "No way, that looks scary!";

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private BarrowsSarcophagusMemoryConfig config;

    @Inject
    private ConfigManager configManager;

    @Inject
    private BarrowsSarcophagusMemoryOverlay overlay;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private InfoBoxManager infoBoxManager;

    private BarrowsBrother pendingBrother;
    private int pendingBrotherTicksRemaining;
    private BarrowsBrother tunnelBrother;
    private final Set<BarrowsBrother> emptyBrothers = EnumSet.noneOf(BarrowsBrother.class);
    private TunnelBrotherInfoBox tunnelInfoBox;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);

        // Older test builds stored this globally, which could leave stale memory
        // behind and could also share it between RuneScape accounts. Do not
        // migrate that value because it cannot be trusted.
        configManager.unsetConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            TUNNEL_BROTHER_CONFIG_KEY);

        clientThread.invokeLater(() ->
        {
            loadPersistedMemory();
            syncInfoBox();
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        clearPendingBrother();
        removeInfoBox();
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!isGameObjectAction(event.getMenuAction()))
        {
            return;
        }

        if (getCurrentRegionId() != CRYPT_REGION_ID)
        {
            return;
        }

        BarrowsBrother clickedBrother = BarrowsBrother.fromSarcophagusObjectId(event.getId());
        if (clickedBrother == null)
        {
            return;
        }

        pendingBrother = clickedBrother;
        pendingBrotherTicksRemaining = PENDING_SARCOPHAGUS_TICKS;
    }


    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        if (pendingBrother == null
            || getCurrentRegionId() != CRYPT_REGION_ID
            || client.getLocalPlayer() == null
            || client.getLocalPlayer().getWorldLocation().getPlane() != 3)
        {
            return;
        }

        NPC npc = event.getNpc();
        if (npc != null && pendingBrother.matchesNpcName(npc.getName()))
        {
            markBrotherEmpty(pendingBrother);
            clearPendingBrother();
        }
    }


    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            loadPersistedMemory();
            removeInfoBox();
            syncInfoBox();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        // The official Barrows Brothers plugin uses this interface to identify
        // the local player's Barrows reward screen. Unlike scene-object changes,
        // this cannot be triggered by another player opening the shared chest.
        if (event.getGroupId() == InterfaceID.BARROWS_REWARD)
        {
            resetMemory();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (pendingBrother != null && isHiddenTunnelDialogueVisible())
        {
            setTunnelBrother(pendingBrother);
            clearPendingBrother();
        }
        else if (pendingBrother != null)
        {
            pendingBrotherTicksRemaining--;
            if (pendingBrotherTicksRemaining <= 0)
            {
                clearPendingBrother();
            }
        }

        syncInfoBox();
    }


    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!BarrowsSarcophagusMemoryConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        clientThread.invokeLater(() ->
        {
            removeInfoBox();
            syncInfoBox();
        });
    }

    BarrowsBrother getTunnelBrother()
    {
        return tunnelBrother;
    }

    boolean isBrotherEmpty(BarrowsBrother brother)
    {
        return emptyBrothers.contains(brother);
    }

    private void setTunnelBrother(BarrowsBrother brother)
    {
        if (tunnelBrother == brother)
        {
            syncInfoBox();
            return;
        }

        tunnelBrother = brother;
        if (emptyBrothers.remove(brother))
        {
            persistEmptyBrothers();
        }
        configManager.setRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            TUNNEL_BROTHER_CONFIG_KEY,
            brother.name());
        removeInfoBox();
        syncInfoBox();
    }

    private void resetMemory()
    {
        tunnelBrother = null;
        emptyBrothers.clear();
        configManager.unsetRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            TUNNEL_BROTHER_CONFIG_KEY);
        configManager.unsetRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            EMPTY_BROTHERS_CONFIG_KEY);
        configManager.unsetConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            TUNNEL_BROTHER_CONFIG_KEY);
        clearPendingBrother();
        removeInfoBox();
    }

    private void loadPersistedMemory()
    {
        emptyBrothers.clear();

        String persistedEmptyBrothers = configManager.getRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            EMPTY_BROTHERS_CONFIG_KEY);

        if (persistedEmptyBrothers != null && !persistedEmptyBrothers.trim().isEmpty())
        {
            for (String value : persistedEmptyBrothers.split(","))
            {
                try
                {
                    emptyBrothers.add(BarrowsBrother.valueOf(value.trim()));
                }
                catch (IllegalArgumentException ignored)
                {
                    // Ignore invalid values and rewrite the cleaned set below.
                }
            }
            persistEmptyBrothers();
        }

        String persistedBrother = configManager.getRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            TUNNEL_BROTHER_CONFIG_KEY);

        if (persistedBrother == null || persistedBrother.isEmpty())
        {
            tunnelBrother = null;
            solveTunnelByElimination();
            return;
        }

        try
        {
            tunnelBrother = BarrowsBrother.valueOf(persistedBrother);
            if (emptyBrothers.remove(tunnelBrother))
            {
                persistEmptyBrothers();
            }
        }
        catch (IllegalArgumentException ex)
        {
            tunnelBrother = null;
            configManager.unsetRSProfileConfiguration(
                BarrowsSarcophagusMemoryConfig.GROUP,
                TUNNEL_BROTHER_CONFIG_KEY);
            solveTunnelByElimination();
        }
    }

    private void markBrotherEmpty(BarrowsBrother brother)
    {
        if (brother == null || brother == tunnelBrother || !emptyBrothers.add(brother))
        {
            return;
        }

        persistEmptyBrothers();
        solveTunnelByElimination();
    }

    private void solveTunnelByElimination()
    {
        if (tunnelBrother != null || emptyBrothers.size() != BarrowsBrother.values().length - 1)
        {
            return;
        }

        for (BarrowsBrother brother : BarrowsBrother.values())
        {
            if (!emptyBrothers.contains(brother))
            {
                setTunnelBrother(brother);
                return;
            }
        }
    }

    private void persistEmptyBrothers()
    {
        if (emptyBrothers.isEmpty())
        {
            configManager.unsetRSProfileConfiguration(
                BarrowsSarcophagusMemoryConfig.GROUP,
                EMPTY_BROTHERS_CONFIG_KEY);
            return;
        }

        String value = emptyBrothers.stream()
            .map(Enum::name)
            .sorted()
            .collect(Collectors.joining(","));

        configManager.setRSProfileConfiguration(
            BarrowsSarcophagusMemoryConfig.GROUP,
            EMPTY_BROTHERS_CONFIG_KEY,
            value);
    }

    private void clearPendingBrother()
    {
        pendingBrother = null;
        pendingBrotherTicksRemaining = 0;
    }

    private void syncInfoBox()
    {
        boolean shouldShow = config.showTunnelInfoBox()
            && isInfoBoxRegion(getCurrentRegionId());

        if (!shouldShow)
        {
            removeInfoBox();
            return;
        }

        if (tunnelInfoBox == null)
        {
            tunnelInfoBox = new TunnelBrotherInfoBox(
                createInfoBoxImage(tunnelBrother),
                this,
                tunnelBrother,
                config);
            infoBoxManager.addInfoBox(tunnelInfoBox);
        }
    }

    private void removeInfoBox()
    {
        if (tunnelInfoBox == null)
        {
            return;
        }

        infoBoxManager.removeInfoBox(tunnelInfoBox);
        tunnelInfoBox = null;
    }

    private int getCurrentRegionId()
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
        {
            return -1;
        }

        return localPlayer.getWorldLocation().getRegionID();
    }

    private static boolean isInfoBoxRegion(int regionId)
    {
        return regionId == ABOVE_GROUND_REGION_ID || regionId == CRYPT_REGION_ID;
    }

    private static boolean isGameObjectAction(MenuAction menuAction)
    {
        return menuAction == MenuAction.GAME_OBJECT_FIRST_OPTION
            || menuAction == MenuAction.GAME_OBJECT_SECOND_OPTION
            || menuAction == MenuAction.GAME_OBJECT_THIRD_OPTION
            || menuAction == MenuAction.GAME_OBJECT_FOURTH_OPTION
            || menuAction == MenuAction.GAME_OBJECT_FIFTH_OPTION;
    }

    private boolean isHiddenTunnelDialogueVisible()
    {
        Widget options = client.getWidget(ComponentID.DIALOG_OPTION_OPTIONS);
        if (options == null || options.isHidden())
        {
            return false;
        }

        return widgetTreeContainsExactText(options, HIDDEN_TUNNEL_PROMPT)
            && widgetTreeContainsExactText(options, HIDDEN_TUNNEL_YES)
            && widgetTreeContainsExactText(options, HIDDEN_TUNNEL_NO);
    }

    private static boolean widgetTreeContainsExactText(Widget root, String expectedText)
    {
        if (widgetHasExactText(root, expectedText))
        {
            return true;
        }

        if (childrenContainExactText(root.getDynamicChildren(), expectedText))
        {
            return true;
        }

        if (childrenContainExactText(root.getStaticChildren(), expectedText))
        {
            return true;
        }

        return childrenContainExactText(root.getNestedChildren(), expectedText);
    }

    private static boolean childrenContainExactText(Widget[] children, String expectedText)
    {
        if (children == null)
        {
            return false;
        }

        for (Widget child : children)
        {
            if (child != null && widgetHasExactText(child, expectedText))
            {
                return true;
            }
        }

        return false;
    }

    private static boolean widgetHasExactText(Widget widget, String expectedText)
    {
        String text = widget.getText();
        if (text == null)
        {
            return false;
        }

        return expectedText.equals(Text.removeTags(text).trim());
    }

    private BufferedImage createInfoBoxImage(BarrowsBrother brother)
    {
        BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();

        try
        {
            graphics.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);

            Color iconColor = brother == null
                ? config.brotherTileColor()
                : config.tunnelSarcophagusColor();
            graphics.setColor(new Color(24, 18, 28, 230));
            graphics.fillRoundRect(1, 1, 30, 30, 8, 8);

            graphics.setColor(iconColor);
            graphics.drawRoundRect(1, 1, 29, 29, 8, 8);

            graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 17));
            String initial = brother == null
                ? "?"
                : brother.getDisplayName().substring(0, 1);
            FontMetrics fontMetrics = graphics.getFontMetrics();
            int x = (32 - fontMetrics.stringWidth(initial)) / 2;
            int y = ((32 - fontMetrics.getHeight()) / 2) + fontMetrics.getAscent();
            graphics.drawString(initial, x, y);
        }
        finally
        {
            graphics.dispose();
        }

        return image;
    }

    @Provides
    BarrowsSarcophagusMemoryConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BarrowsSarcophagusMemoryConfig.class);
    }
}

